def version_tuple(s):
    """Convert a version string like '1.2.3' to a tuple of ints for comparison.
    Split on dots, strip leading/trailing spaces, and convert non-empty parts to ints.
    Empty parts are ignored (e.g., '1..2' -> (1,2)). If a part is not a valid int, raise ValueError (but in this function we assume valid).
    Comparison is lexicographic; shorter tuples are smaller if equal prefix. Example: version_tuple('1.2') -> (1, 2)."""
    parts = s.split('.')
    result = []
    for p in parts:
        p = p.strip()
        if p != '':
            result.append(int(p))
    return tuple(result)

for args in [('1.2',), ('2.0',), ('10.0.1',)]:
    print(version_tuple(*args))

def unique_everseen_with_min(seq):
    """Return list with duplicates dropped, preserving order, but for each duplicate keep min value overall.
    Ties keep earlier position. Empty input returns empty list. Elements must be comparable.
    Example: unique_everseen_with_min([2,1,2,3,1]) -> [2,1,3]"""
    seen = dict()
    for (index, value) in enumerate(seq):
        if value not in seen:
            seen[value] = index
        elif value < seen[value]:
            pass
    seen2 = set()
    result = []
    for x in seq:
        if x not in seen2:
            seen2.add(x)
            result.append(x)
    return result

print(unique_everseen_with_min([3,2,1,2,3]))

